CREATE FUNCTION pg_temp.scan_stem(p_key text) RETURNS text
    LANGUAGE sql IMMUTABLE AS $$ SELECT regexp_replace(p_key, '^.*/|\.[A-Za-z0-9]+$', '', 'g') $$;

-- ---------- baskets: every new buyer has one, with one to four cards in it ----------
INSERT INTO cart (user_id, session_key, created_at, updated_at, expires_at)
SELECT b.user_id, NULL, pg_temp.ago(1 + abs(hashtext(b.username)) % 6), pg_temp.ago(abs(hashtext(b.username)) % 3 * 0.4), NULL
  FROM seed_new_buyer b;

INSERT INTO cart_item (cart_id, listing_id, quantity, unit_price_at_add, added_at, updated_at)
SELECT c.id, x.listing_id, 1, x.price, pg_temp.ago(x.k * 0.3), pg_temp.ago(x.k * 0.3)
  FROM seed_new_buyer b
  JOIN cart c ON c.user_id = b.user_id
  CROSS JOIN LATERAL (
        SELECT l.id AS listing_id, l.price, row_number() OVER (ORDER BY md5(b.username || l.id)) AS k
          FROM listing l
          JOIN seller_profile sp ON sp.id = l.seller_profile_id
         WHERE l.status = 'ACTIVE' AND l.quantity_available > 0 AND sp.status = 'VERIFIED' AND NOT sp.vacation_mode
           AND sp.user_id <> b.user_id
         ORDER BY md5(b.username || l.id)
         LIMIT 1 + abs(hashtext(b.username || 'cart')) % 4) x;

-- ---------- wish lists: three to eight cards each, some with a target price ----------
INSERT INTO wishlist_item (user_id, catalog_variant_id, target_price, created_at)
SELECT b.user_id, x.id,
       CASE WHEN x.k % 3 = 0 THEN NULL ELSE round(x.median * 0.85 / 10) * 10 END,
       pg_temp.ago(2 + (abs(hashtext(b.username || x.id)) % 80))
  FROM seed_new_buyer b
  CROSS JOIN LATERAL (
        SELECT cv.id, avg(l.price) AS median, row_number() OVER (ORDER BY md5(b.username || cv.id || 'w')) AS k
          FROM catalog_variant cv JOIN listing l ON l.catalog_variant_id = cv.id AND l.status = 'ACTIVE'
         GROUP BY cv.id
         ORDER BY md5(b.username || cv.id || 'w')
         LIMIT 3 + abs(hashtext(b.username || 'wish')) % 6) x;

-- ---------- collections: cards people already owned and typed in themselves ----------
INSERT INTO collection_item (user_id, catalog_variant_id, condition_code, quantity, source, grading_company, grade_value,
                             cert_number, acquired_price, acquired_at, image_key, personal_note, is_public,
                             created_at, updated_at)
SELECT b.user_id, x.id, x.cond, x.qty, 'MANUAL', x.grader,
       CASE WHEN x.grader IS NOT NULL THEN x.grade END,
       CASE WHEN x.grader IS NOT NULL THEN x.grader || ' ' || (10000000 + abs(hashtext(b.username || x.id)) % 89999999) END,
       round(x.price * (0.6 + (x.k % 5) * 0.12)), pg_temp.ago(30 + abs(hashtext(x.id || b.username)) % 300),
       x.image_key,
       (ARRAY['เปิดได้จากซองเอง', 'แลกมาจากงานเทรด', 'ใบโปรดในแฟ้ม', NULL, 'ซื้อจากร้านแถวบ้าน', 'เก็บไว้ไม่เล่น',
              'ใช้ในเด็คแข่ง', NULL, 'ได้จากกล่องที่เปิดกับเพื่อน'])[1 + x.k % 9],
       x.k % 7 <> 0, pg_temp.ago(5 + abs(hashtext(b.username || x.id)) % 200), pg_temp.ago(5 + abs(hashtext(b.username || x.id)) % 200)
  FROM seed_new_buyer b
  CROSS JOIN LATERAL (
        SELECT cv.id, CASE WHEN p.product_type = 'SINGLE_CARD' THEN (ARRAY['NM', 'NM', 'NM', 'LP', 'MP'])[1 + abs(hashtext(cv.sku || b.username)) % 5] ELSE 'SEALED' END AS cond,
               CASE WHEN p.product_type = 'SINGLE_CARD' THEN 1 + abs(hashtext(b.username || cv.sku)) % 3 / 2 ELSE 1 END AS qty,
               CASE WHEN p.product_type = 'SINGLE_CARD' AND abs(hashtext(cv.sku || b.username || 'g')) % 6 = 0
                    THEN (ARRAY['PSA', 'BGS', 'CGC'])[1 + abs(hashtext(cv.sku)) % 3] END AS grader,
               (ARRAY[10, 9, 9.5, 10, 8])[1 + abs(hashtext(cv.sku || 'grade')) % 5]::numeric AS grade,
               avg(l.price) AS price,
               (SELECT ci.image_key FROM catalog_image ci WHERE ci.catalog_product_id = p.id AND ci.is_primary) AS image_key,
               row_number() OVER (ORDER BY md5(b.username || cv.id || 'c')) AS k
          FROM catalog_variant cv
          JOIN catalog_product p ON p.id = cv.catalog_product_id AND p.product_type <> 'ACCESSORY'
          JOIN listing l ON l.catalog_variant_id = cv.id
         GROUP BY cv.id, p.id
         ORDER BY md5(b.username || cv.id || 'c')
         LIMIT 3 + abs(hashtext(b.username || 'coll')) % 13) x;

-- Most collectors show off a few of the cards they bought here.
UPDATE collection_item ci
   SET is_public = true, personal_note = coalesce(ci.personal_note, 'ซื้อจาก Pegasus')
 WHERE ci.source = 'PURCHASE' AND ci.user_id IN (SELECT user_id FROM seed_new_buyer)
   AND abs(hashtext(ci.id::text)) % 3 <> 0;

-- ---------- the sellers' own photos ----------
-- Every listing shows photos the shop took: the card on a playmat, in a toploader and a close-up of a
-- corner (slabs: the slab itself), then the official scan. They are drawn at seed time from the scan
-- of the printing the listing sells (seed/gen/<view>/<scan file>.jpg; render-manifest.sql lists them).
CREATE TEMP TABLE seed_listing_scan ON COMMIT DROP AS
SELECT l.id AS listing_id, l.created_at, l.grading_company, l.grade_value, l.condition_code,
       coalesce((SELECT ci.image_key FROM catalog_image ci WHERE ci.catalog_variant_id = l.catalog_variant_id
                  ORDER BY ci.sort_order LIMIT 1),
                (SELECT ci.image_key FROM catalog_image ci WHERE ci.catalog_product_id = cv.catalog_product_id AND ci.is_primary)) AS scan,
       p.product_type, p.id AS product_id, 2 + abs(hashtext(l.id::text)) % 3 AS n
  FROM listing l
  JOIN catalog_variant cv ON cv.id = l.catalog_variant_id
  JOIN catalog_product p ON p.id = cv.catalog_product_id
 WHERE EXISTS (SELECT 1 FROM listing_image li WHERE li.listing_id = l.id);

DELETE FROM listing_image WHERE listing_id IN (SELECT listing_id FROM seed_listing_scan);

INSERT INTO listing_image (listing_id, image_key, sort_order, is_primary, created_at)
SELECT s.listing_id, x.key, (x.ord - 1)::smallint, x.ord = 1, s.created_at
  FROM seed_listing_scan s
  CROSS JOIN LATERAL (
        SELECT key, ord FROM (
            SELECT k.key, k.ord
              FROM unnest(CASE
                  WHEN s.product_type = 'ACCESSORY' THEN
                       ARRAY(SELECT ci.image_key FROM catalog_image ci WHERE ci.catalog_product_id = s.product_id
                              ORDER BY ci.is_primary DESC, ci.sort_order)
                  WHEN s.product_type <> 'SINGLE_CARD' THEN
                       ARRAY['seed/gen/table/' || pg_temp.scan_stem(s.scan) || '.jpg', s.scan,
                             'seed/gen/detail/' || pg_temp.scan_stem(s.scan) || '.jpg']
                  WHEN s.grading_company IS NOT NULL THEN
                       ARRAY['seed/gen/slab/' || pg_temp.scan_stem(s.scan) || '--' || lower(s.grading_company) || '-'
                             || replace(regexp_replace(s.grade_value::text, '\.0+$', ''), '.', '_') || '.jpg', s.scan]
                  ELSE ARRAY['seed/gen/mat/' || pg_temp.scan_stem(s.scan) || '.jpg',
                             s.scan,
                             'seed/gen/toploader/' || pg_temp.scan_stem(s.scan) || '.jpg',
                             'seed/gen/corner/' || pg_temp.scan_stem(s.scan) || '.jpg'] END)
                   WITH ORDINALITY AS k(key, ord)) y
         WHERE y.ord <= CASE WHEN s.grading_company IS NOT NULL OR s.product_type <> 'SINGLE_CARD' THEN 3 ELSE s.n + 1 END) x;

-- ---------- 90 days of price history for the cards people watch most ----------
INSERT INTO variant_market_stat (catalog_variant_id, condition_code, stat_date, median_price, avg_price, min_price,
                                 max_price, p25_price, p75_price, active_listing_count, sold_quantity_30d,
                                 sample_size, computed_at)
SELECT s.catalog_variant_id, s.condition_code, s.stat_date - d.n,
       round(s.median_price * f.k, 2), round(s.avg_price * f.k, 2), round(s.min_price * f.k, 2),
       round(s.max_price * f.k, 2), round(s.p25_price * f.k, 2), round(s.p75_price * f.k, 2),
       s.active_listing_count, greatest(0, s.sold_quantity_30d - d.n / 20), s.sample_size,
       s.computed_at - make_interval(days => d.n)
  FROM variant_market_stat s
 CROSS JOIN generate_series(1, 60) AS d(n)
 CROSS JOIN LATERAL (
        SELECT round((1 + 0.0035 * (30 + d.n) * CASE WHEN s.catalog_variant_id % 2 = 0 THEN 1 ELSE -1 END
                      + 0.04 * sin((30 + d.n) / 4.0 + s.catalog_variant_id))::numeric, 4) AS k) AS f
 WHERE s.stat_date = (SELECT min(stat_date) FROM variant_market_stat)
   AND s.active_listing_count >= 3;

-- ---------- more home page slides for the newer sets ----------
INSERT INTO home_banner (display_order, eyebrow, title, description, image_key, image_alt, theme, primary_label,
                         primary_href, secondary_label, secondary_href, is_active, starts_at, ends_at,
                         created_at, updated_at)
SELECT v.ord::smallint, v.eyebrow, replace(v.title, '\n', E'\n'), v.description,
       (SELECT ci.image_key FROM catalog_image ci JOIN catalog_product p ON p.id = ci.catalog_product_id
         WHERE p.slug = v.slug AND ci.is_primary),
       v.alt, v.theme, v.p_label, v.p_href, v.s_label, v.s_href, true, NULL, NULL,
       pg_temp.ago(v.created_days), pg_temp.ago(v.created_days)
  FROM (VALUES
        (9, 'POKEMON ME02', 'PHANTASMAL\nFLAMES', 'เมก้าลิซาร์ดอน X ex และการ์ดภาพพิเศษจากชุดล่าสุด ส่งไวจากร้านในไทย', 'pfl-phantasmal-flames-booster-box', 'PHANTASMAL FLAMES', 'RELEASE', 'ช้อป Phantasmal Flames', '/search?q=Phantasmal%20Flames', 'โปเกมอนทั้งหมด'::text, '/search?game=pokemon-tcg'::text, 8::numeric),
        (10, 'ONE PIECE OP-16', 'THE TIME\nOF BATTLE', 'การ์ดมังงะอาร์ต SR และ SEC ของ OP-16 พร้อมส่ง', 'op16-the-time-of-battle-booster-box', 'THE TIME OF BATTLE', 'CAMPAIGN', 'ช้อป OP-16', '/search?q=OP16', 'ร้าน Straw Hat Market', '/u/strawhat_market', 12),
        (11, 'UNION ARENA', 'CHAINSAW MAN\nมาแล้ว', 'มาคิมะ เรเซ่ พาวเวอร์ ครบทุกระดับดาว', 'ue22bt-chainsaw-man-booster-box', 'CHAINSAW MAN มาแล้ว', 'COLLECTOR', 'ช้อป Chainsaw Man', '/search?q=Chainsaw%20Man', 'ร้าน Anime Arena Cards', '/u/anime_arena_cards', 6),
        (12, 'MAGIC: THE GATHERING', 'MARVEL''S\nSPIDER-MAN', 'การ์ด Borderless และ Textured Foil จาก Spider-Man', 'spm-marvels-spider-man-play-booster-display', 'MARVEL''S SPIDER-MAN', 'RELEASE', 'ช้อป Magic', '/search?game=magic-the-gathering', NULL, NULL, 20)
       ) AS v(ord, eyebrow, title, description, slug, alt, theme, p_label, p_href, s_label, s_href, created_days)
 WHERE EXISTS (SELECT 1 FROM catalog_product p WHERE p.slug = v.slug);
